// Sweep leftovers of an aborted earlier run before the first sequence. Matrix 9-11 sweep too, but they
// sit after 12-17 in collection order, so a stale second anthropic key would serve every sequence first.
// Only objects older than ten minutes are swept, as in matrix 9-11: another harness run against the
// same gateway may be mid-matrix, and its objects are live however this run is sharded.
(function () {
  var BASE = pm.variables.get('baseUrl');
  function isStale(name, prefix) {
    var m = String(name || '').indexOf(prefix) === 0 && String(name).match(/run-(\d+)/);
    return !!(m && (Date.now() - Number(m[1])) > 10 * 60 * 1000);
  }
  function list(path, field, prefix, cb) {
    pm.sendRequest({ url: BASE + path, method: 'GET' }, function (err, res) {
      var json = null; try { json = res.json(); } catch (e) { json = null; }
      cb(((json && json[field]) || []).filter(function (o) { return isStale(o.name, prefix); }));
    });
  }
  function deleteEach(items, pathOf, done) {
    var i = 0; (function next() { if (i >= items.length) { return done(); } var it = items[i++]; pm.sendRequest({ url: BASE + pathOf(it), method: 'DELETE' }, function () { next(); }); })();
  }
  list('/api/governance/routing-rules', 'rules', 'Harness session matrix ', function (rules) {
    deleteEach(rules, function (r) { return '/api/governance/routing-rules/' + r.id; }, function () {
      list('/api/governance/virtual-keys', 'virtual_keys', 'harness-session-matrix-', function (vks) {
        deleteEach(vks, function (v) { return '/api/governance/virtual-keys/' + v.id; }, function () {
          list('/api/providers/anthropic/keys', 'keys', 'Harness Session Key B ', function (keys) {
            deleteEach(keys, function (k) { return '/api/providers/anthropic/keys/' + k.id; }, function () {});
          });
        });
      });
    });
  });
})();

